INSERT INTO client_releases (version, version_key, platform, file_key, file_name, size, sha256, notes, notes_en, published_at) VALUES ('2.96.0', 2096000, 'windows', 'releases/CosmicPlatformer-Setup-2.96.0.exe', 'CosmicPlatformer-Setup-2.96.0.exe', 161236476, '3a79ffeae76e4a4dac866585e66ecb5c401813560351a25de494091d3a81dafb', 'Version 2.96.0 :
• Raids : chat de groupe et chat du raid, comme dans Minecraft (T, Partage, ou menu du raid › Groupe) — canaux « Groupe » et « Raid » (Tab, RB, /g, /r), messages rapides à la manette, réglable dans l''éditeur du HUD ; à terre ou éliminé on écrit toujours ; en test local, les pensées des joueurs simulés s''y affichent (« IA »).
• Raid simulé (test local) : un groupe dont le Gigaboss est tombé reste en attente dans sa branche et n''en part que pour remplacer un groupe éliminé, là où il est tombé ; le 8e groupe double le Torse ; le Cœur, combattu à plusieurs instances, n''a qu''une seule barre de vie ; les joueurs simulés ne restent plus bloqués aux monte-charges, aux échelles du Poignet-verrou ni aux plaques jumelles : chaque groupe atteint son Gigaboss.
• TAS : les états sauvegardés de la recherche (cosmic_tas) sont vérifiés pas à pas et sans dépendre de la mémoire inutilisée, sous Windows comme sous Linux.', 'Version 2.96.0:
• Raids: group chat and raid-wide chat, Minecraft-style (T, Share, or raid menu › Group) — "Group" and "Raid" channels (Tab, RB, /g, /r), quick messages on gamepad, adjustable in the HUD editor; downed or eliminated players can still chat; in local tests the simulated players'' thoughts show up there ("AI").
• Simulated raid (local test): a group whose Gigaboss has fallen waits in its branch and only leaves it to replace a wiped group, where it fell; the 8th group doubles the Torso; the Heart, fought in several instances, has a single health bar; simulated players no longer get stuck at goods lifts, the Lock Wrist''s ladders or the twin plates: every group reaches its Gigaboss.
• TAS: the search''s saved states (cosmic_tas) are checked step by step and without depending on unused memory, on Windows as on Linux.', '2026-11-27T15:36:56.232Z') ON CONFLICT (version) DO NOTHING;
